#!/usr/bin/env node
/**
 * fleet/doctor.mjs — "do you have a fleet?"
 *
 * The one piece of `fleet/` that runs on a user's laptop, straight out of the
 * installed plugin cache, where no `node_modules` directory under `fleet/` has
 * ever existed. Hence the built-ins-only rule: every specifier here is
 * `node:`-prefixed or a sibling fleet module that is itself built-ins-only —
 * the config and policy readers come from `./lobby.mjs`, one copy for both
 * the doctor and the launcher.
 *
 * Nine rows, all reads, every one of them answered by exe.dev's own truth or
 * by this laptop's own keychain:
 *
 *   exe-dev       `ssh exe.dev whoami` names an account.
 *   capacity      `billing plan --json` names the pool, beside the size one
 *                 run asks for. The row reports; it limits nothing.
 *   claude        the `claude-max` integration carries the bearer at the edge;
 *                 claude-token's status line rides along.
 *   accounts      `claude-token.mjs accounts --json` lists every keychain
 *                 entry with its expiry, and the row says which account the
 *                 edge carries and whether the config names one the keychain
 *                 does not hold.
 *   github        `integrations setup github --list` lists an account.
 *   integrations  every integration a run needs — `claude-max`, and with
 *                 `--target` the target's own `gh-<owner>-<repo>` — carries the
 *                 attachment policy `tag:fleet` (`integrations policy get
 *                 <name> --json`, `policy.selector`). That policy is the one
 *                 way a credential reaches a fleet VM: exe.dev refuses `new
 *                 --integration` and `integrations attach` since 2026-09-11.
 *   verb-drift    `help <verb>` for every verb in the verb record, and
 *                 the diff against the flags recorded there. A flag that
 *                 appeared or vanished is a finding in a green row; only a
 *                 record the doctor cannot read turns it red.
 *   kata          the hub is there: the `kata` http-proxy carries a bearer at
 *                 the edge, its attachment policy is `tag:fleet` (`integrations
 *                 policy get kata --json`, `policy.selector` — never the
 *                 listing's `attachments`, which name the VMs the policy
 *                 currently resolves to), and `ls kata-hub --json` answers a
 *                 `kata-hub` row. All three, or the row says which is absent.
 *   cloudflare    the deploy's credential, needed only by a plan with a
 *                 `**Publish:**` line. Absent is green — most plans never
 *                 publish — and a present object is green on the fleet's
 *                 policy, `tag:fleet`, and red off it.
 *
 * Running the doctor twice is the same as running it once: nothing here
 * creates, copies or removes a VM, and nothing writes a file. A red row names
 * the `references/first-run.md` section that builds the piece and, where there
 * is one, the exact command.
 *
 * There are no token rows, because after the lift no token is on any disk the
 * doctor could stat: the Claude subscription reaches a sandbox through the
 * `claude-max` http-proxy integration, whose bearer is injected at exe.dev's
 * edge, and GitHub reaches it through the target's one integration
 * `gh-<owner>-<repo>`. `integrations test claude-max` is not a check for an
 * http-proxy (measured 2026-09-04: it answers "test connection is available
 * for catalog and database integrations"), so the bearer's presence in the
 * listing is the edge-side truth the doctor can read.
 */

import { execFile } from 'node:child_process'
import fsp from 'node:fs/promises'
import path from 'node:path'
import { promisify } from 'node:util'
import { fileURLToPath } from 'node:url'

import {
  DEFAULT_CONFIG_PATH,
  FLEET_DEFAULTS,
  VERBS_PATH,
  VERBS_RECORD,
  isSafeTarget,
  loadFleetConfig,
  parseMemoryGb,
  parsePolicy
} from './lobby.mjs'

const execFileAsync = promisify(execFile)

/** The nine rows, in the order the doctor reports them. Each id is also a
 *  `## ` heading in skills/ultrapowers/references/first-run.md. */
export const ROW_IDS = Object.freeze([
  'exe-dev', 'capacity', 'claude', 'accounts', 'github', 'integrations', 'verb-drift', 'kata', 'cloudflare'
])

/** Each row's `fix` is the `## ` heading in first-run.md that repairs it, and
 *  every row id is its own heading. */
const FIXES = Object.freeze(Object.fromEntries(ROW_IDS.map((id) => [id, id])))

/** The doctor's own directory: claude-token.mjs sits beside this file, and the
 *  doctor runs it rather than importing it, so its keychain access stays out of
 *  a process that has to start when nothing else in the fleet does. */
const HERE = path.dirname(fileURLToPath(import.meta.url))
const CLAUDE_TOKEN = path.join(HERE, 'claude-token.mjs')

/** The eight standing reads, in the order the doctor issues them. One policy
 *  read per integration the `integrations` row asks about follows them, then
 *  the `help` reads of the verb-drift row, one per verb of the record;
 *  together they are the only commands the doctor ever runs.
 *
 *  The last two are the `kata` row's. Its policy read is spelled out rather
 *  than taken from `policyRead`, because it is a standing read of a fixed name
 *  and not one of the names the `integrations` row computes; and the hub is the
 *  one thing the doctor asks `ls` about, every other row reading edge-side
 *  objects the listing already carries. */
const READS = Object.freeze({
  whoami: 'ssh exe.dev whoami',
  billing: 'ssh exe.dev "billing plan --json"',
  list: 'ssh exe.dev "integrations list --json"',
  github: 'ssh exe.dev "integrations setup github --list"',
  token: `node ${CLAUDE_TOKEN} status`,
  usage: `node ${CLAUDE_TOKEN} usage --json --no-rotate`,
  accounts: `node ${CLAUDE_TOKEN} accounts --json`,
  kataPolicy: 'ssh exe.dev "integrations policy get kata --json"',
  kataVm: 'ssh exe.dev "ls kata-hub --json"'
})

/** The policy read for one integration — the only read of a name. */
export const policyRead = (name) => `ssh exe.dev "integrations policy get ${name} --json"`

/** The tag a fleet VM is created with, the policy every fleet integration
 *  carries, and the integration that carries the bearer. */
const TAG = 'fleet'
const FLEET_POLICY = `tag:${TAG}`
const OAUTH_INTEGRATION = 'claude-max'

/** The legacy per-account runs integration, still recognised by name so a fleet
 *  that predates the lift is told to detach it. Assembled rather than spelled
 *  out because no file under `fleet/` may carry that literal any more. */
const LEGACY_RUNS = ['fleet', 'runs'].join('-')

/** The bearer the edge injects, as the listing spells it. */
const BEARER = 'Authorization:Bearer'

const row = (id, status, detail) => ({ id, status, detail, fix: FIXES[id] })
const firstLine = (stdout) => String(stdout ?? '').split('\n')[0].trim()

/** `owner/repo` → the target's one integration object, `gh-<owner>-<repo>`. */
const targetIntegration = (target) => `gh-${String(target).replace(/\//g, '-')}`

const parseCpus = (value) => (/^\d+$/.test(String(value ?? '').trim()) ? Number(value) : null)

/**
 * The config file's own top-level key names, in file order — `loadFleetConfig`
 * answers what the doctor reads, this answers what the operator wrote. Null
 * when the file is absent, unreadable, not JSON, or not a JSON object, because
 * none of those is a file carrying keys.
 *
 * The two travel separately on purpose: `result.config` is exactly the doctor's
 * two keys, so a name the doctor does not read reaches the `capacity` row on
 * `configKeys` and never through the config.
 */
async function fleetConfigKeys ({ path: configPath } = {}) {
  const target = configPath ?? DEFAULT_CONFIG_PATH()
  let text
  try {
    text = await fsp.readFile(target, 'utf8')
  } catch {
    return null
  }
  let parsed
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null
  return Object.keys(parsed)
}

/**
 * The config file's default account: its top-level `account`, or null when the
 * file is absent, is not JSON, is not a JSON object, or names no account. The
 * launcher reads the same key to pick the keychain entry a run signs in with;
 * the doctor reads it only to ask whether the keychain holds that name.
 *
 * It travels beside `loadFleetConfig` rather than inside it: `result.config` is
 * exactly the two keys the doctor itself reads, and the account reaches
 * `doctor()` as its own option.
 */
export async function fleetConfigAccount ({ path: configPath } = {}) {
  const target = configPath ?? DEFAULT_CONFIG_PATH()
  let text
  try {
    text = await fsp.readFile(target, 'utf8')
  } catch {
    return null
  }
  let parsed
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null
  const account = parsed.account
  return typeof account === 'string' && account !== '' ? account : null
}

/** The exec seam: resolve `{ code, stdout }`, never reject, so a test drives
 *  every row with a stub and the CLI drives them with a shell. stderr joins
 *  stdout because claude-token logs its status line there. */
export async function defaultExec (cmd) {
  try {
    const { stdout, stderr } = await execFileAsync('/bin/sh', ['-c', cmd], {
      maxBuffer: 10 * 1024 * 1024
    })
    return { code: 0, stdout: stdout + stderr }
  } catch (error) {
    return {
      code: error?.code ?? 1,
      stdout: (error?.stdout ?? '') + (error?.stderr ?? '')
    }
  }
}

// ── exe-dev ──────────────────────────────────────────────────────────────────

function exeDevRow (res) {
  const who = firstLine(res.stdout)
  if (res.code === 0 && who !== '') return row('exe-dev', 'ok', `signed in as ${who}`)
  return row('exe-dev', 'missing', `ssh exe.dev whoami answered code ${res.code} with no account name`)
}

// ── capacity ─────────────────────────────────────────────────────────────────

/**
 * `billing plan --json` is one flat object with `max_cpus`, `max_memory_gb`,
 * `tier` and `plan`. The row reports two numbers side by side — the pool, and
 * the size one run asks for — and draws no conclusion from them, because
 * allocation on exe.dev is over-committable: 56 vCPU stood allocated against a
 * 16-vCPU plan and no run was ever refused (measured 2026-09-05). A pool
 * smaller than the ask is therefore a green row that says so, not a limit.
 *
 * Only a number the doctor could not read turns the row red: an unreadable
 * `billing plan --json`, or a `cpu`/`memory` it cannot parse. Both details name
 * `~/.ultrapowers/fleet.json`, the file that sets the size a run asks for.
 */
function poolRow (res, config) {
  const askedCpu = parseCpus(config.cpu)
  const askedGb = parseMemoryGb(config.memory)
  if (askedCpu === null || askedGb === null) {
    return row(
      'capacity',
      'missing',
      `~/.ultrapowers/fleet.json asks for cpu ${config.cpu} / memory ${config.memory}, which is not <int> and <int>GB`
    )
  }

  const plan = res.code === 0 ? readJson(res.stdout) : null
  const poolCpu = typeof plan?.max_cpus === 'number' ? plan.max_cpus : null
  const poolGb = typeof plan?.max_memory_gb === 'number' ? plan.max_memory_gb : null
  if (poolCpu === null || poolGb === null) {
    return row(
      'capacity',
      'missing',
      `billing plan --json answered code ${res.code} with no readable pool — ~/.ultrapowers/fleet.json sets the size a run asks for`
    )
  }

  const tier = typeof plan.tier === 'string' && plan.tier !== '' ? plan.tier : String(plan.plan ?? 'untiered')
  const pool = `${tier} pool ${poolCpu} vCPU / ${poolGb}GB`
  const asked = `${askedCpu} vCPU / ${askedGb}GB`
  return row('capacity', 'ok', `${pool}; a run asks ${asked}`)
}

/** The two key names the doctor reads, as the row's detail spells them. */
const READ_KEYS = Object.keys(FLEET_DEFAULTS)

/** The names something outside the doctor reads, as the row's detail spells
 *  them: `account` picks the keychain entry a run signs in with. It is the
 *  launcher's to read; the doctor only asks whether what it names is there. */
const LAUNCHER_KEYS = Object.freeze(['account'])

/** Every name the config file may carry: the two the doctor reads, and the one
 *  the launcher does. A name outside this list is a key nothing reads. */
const CONFIG_KEYS = Object.freeze([...READ_KEYS, ...LAUNCHER_KEYS])

/**
 * The pool arithmetic, plus what the config file's own key names say about it.
 *
 * `configKeys` is `fleetConfigKeys`'s answer for the same file: null when there
 * is no file to read keys off, and otherwise every top-level name in it. A name
 * outside `CONFIG_KEYS` is a key left by a fleet from before the lift — the
 * operator wrote a setting nothing consults, so the row is red until the file is
 * rewritten, and the detail names those keys by echoing the file rather than
 * spelling any of them here. `account` is not among them: the doctor never reads
 * it, but the launcher does, and the `accounts` row says whether what it names is
 * there. A file that omits one of the two the doctor does read is not wrong, only
 * silent, so the green detail says which default it fell back to.
 */
function capacityRow (res, config, configKeys = null) {
  const base = poolRow(res, config)
  const keys = Array.isArray(configKeys) ? configKeys.filter((k) => typeof k === 'string') : null
  if (keys === null) return base

  const stale = keys.filter((key) => !CONFIG_KEYS.includes(key))
  if (stale.length > 0) {
    return row(
      'capacity',
      'missing',
      `~/.ultrapowers/fleet.json carries ${stale.join(', ')} — keys nothing reads; ` +
        `it reads ${READ_KEYS.join(' and ')} only, and the launcher reads ` +
        `${LAUNCHER_KEYS.join(' and ')}. ${base.detail}`
    )
  }
  if (base.status !== 'ok') return base

  const lacking = READ_KEYS.filter((key) => !keys.includes(key))
  const notes = lacking.map(
    (key) => ` (${key} not in ~/.ultrapowers/fleet.json — the default ${FLEET_DEFAULTS[key]})`
  )
  return notes.length === 0 ? base : row('capacity', 'ok', `${base.detail}${notes.join('')}`)
}

// ── integrations, read once for two rows ─────────────────────────────────────

function readJson (stdout) {
  try {
    return JSON.parse(String(stdout ?? ''))
  } catch {
    return null
  }
}

/**
 * `integrations list --json` read defensively. The doctor asks three questions
 * of each object — does it exist, does it carry the bearer, and is it attached
 * to `tag:fleet` — and every answer has to survive a field rename on exe.dev's
 * side without turning a healthy fleet red for the wrong reason. So the reader
 * takes the top level as either an array or an object with an array under
 * `integrations`, a name via `name` or `id`, the bearer via `config_summary` or
 * `config.headers[]`, and attachments via whichever plausible key is present,
 * each entry either the string `tag:fleet` / `vm:fleet-run-3` or an object
 * carrying a `tag` key.
 *
 * Answers a Map of name → `{ name, tags, github, bearer, comment }`, or null
 * when the stdout is not a listing at all. `comment` is the entry's own comment
 * string or null: the credential tool writes `account=<name>` into `claude-max`'s
 * on every install, and the `accounts` row reads the edge's account off it.
 */
function parseIntegrations (stdout) {
  const parsed = readJson(stdout)
  const list = Array.isArray(parsed)
    ? parsed
    : (Array.isArray(parsed?.integrations) ? parsed.integrations : null)
  if (list === null) return null

  const out = new Map()
  for (const entry of list) {
    if (!entry || typeof entry !== 'object') continue
    const name = typeof entry.name === 'string' ? entry.name : entry.id
    if (typeof name !== 'string' || name === '') continue
    out.set(name, {
      name,
      tags: attachedTags(entry),
      github: isGithub(entry, name),
      bearer: hasBearer(entry),
      comment: typeof entry.comment === 'string' ? entry.comment : null
    })
  }
  return out
}

/** Is this entry a GitHub integration? By its declared type, by the repository
 *  field only GitHub objects carry, or by the fleet's own naming. */
function isGithub (entry, name) {
  const type = entry.type ?? entry.kind
  if (type === 'github') return true
  if (typeof entry.repository === 'string' || typeof entry.repo === 'string') return true
  return name === LEGACY_RUNS || name.startsWith('gh-')
}

/** Does this entry carry the Authorization bearer the edge injects? The
 *  measured listing spells it in `config_summary`; a listing that spells it in
 *  `config.headers[]` instead says the same thing. */
function hasBearer (entry) {
  const summary = typeof entry.config_summary === 'string' ? entry.config_summary : ''
  if (summary.replace(/\s+/g, '').includes(BEARER)) return true
  const headers = entry.config?.headers
  if (Array.isArray(headers)) {
    for (const header of headers) {
      if (typeof header === 'string' && header.replace(/\s+/g, '').includes(BEARER)) return true
    }
  }
  return false
}

const ATTACHMENT_KEYS = ['attachments', 'attached', 'attachedTo', 'attached_to', 'targets']

function attachedTags (entry) {
  const tags = new Set()
  for (const key of ATTACHMENT_KEYS) {
    const value = entry[key]
    if (!Array.isArray(value)) continue
    for (const item of value) {
      if (typeof item === 'string' && item.startsWith('tag:')) tags.add(item.slice(4))
      else if (item && typeof item === 'object' && typeof item.tag === 'string') tags.add(item.tag)
    }
  }
  if (Array.isArray(entry.tags)) {
    for (const tag of entry.tags) if (typeof tag === 'string') tags.add(tag)
  }
  return tags
}

/** The fix for a policy that is not `tag:fleet`: the read, then the write
 *  under the revision the read answered. */
const policyFix = (name) =>
  `ssh exe.dev "integrations attach ${name} ${FLEET_POLICY}" (or, when the lobby serves the policy model: ` +
  `ssh exe.dev "integrations policy get ${name} --json" then ` +
  `ssh exe.dev "integrations policy set ${name} '${FLEET_POLICY}' --permanent --if-revision=<revision>")`

/**
 * The one policy question every integration row asks: is the object `name`
 * granted to fleet VMs? The listing is served by both lobby models (#924): an
 * attachment `tag:fleet` in `integrations list --json` is the grant whichever
 * verb set the edge has; only an unattached object is judged by its policy
 * read (`policyRes`, the answer of `integrations policy get <name> --json`).
 *
 * Resolves null when the object is on the policy, otherwise the row `id`
 * reports: an absent object is `ok` with `absentIsOk` (and `absentDetail`),
 * `missing` without; an unreadable or off-policy one is `missing`, naming
 * `policyFix(name)`.
 */
export function policyRowFor (name, { id, found, policyRes, absentIsOk = false, absentDetail = null } = {}) {
  const have = found === null || found === undefined ? undefined : found.get(name)
  if (have === undefined) {
    return row(id, absentIsOk ? 'ok' : 'missing', absentDetail ?? `no ${name} integration at the edge`)
  }
  if (have.tags.has('fleet')) return null
  const policy = policyRes && policyRes.code === 0 ? parsePolicy(policyRes.stdout) : null
  if (policy === null) {
    const seen = policyRes && policyRes.code === 0 ? 'printed no readable policy' : `exited ${policyRes?.code ?? 1}`
    return row(id, 'missing', `integrations policy get ${name} --json ${seen} — ${policyFix(name)}`)
  }
  if (policy.selector === FLEET_POLICY) return null
  return row(
    id,
    'missing',
    `${name} carries the attachment policy ${policy.selector === null ? 'none' : JSON.stringify(policy.selector)} ` +
    `rather than ${FLEET_POLICY}, so no fleet VM is granted it — ${policyFix(name)}`
  )
}
// ── claude ───────────────────────────────────────────────────────────────────

/**
 * `usage --json --no-rotate`'s first row, read for its own detail suffix: the
 * account's seven-day and five-hour windows when the row reads clean, or
 * `usage unread — <reason>` when it does not — a non-zero exit reads as
 * `usage answered code <code>`, an `unread: true` row as its own `reason`.
 * A read never rotates the token; that is the point of `--no-rotate`.
 */
function usageSuffix (usageRes) {
  if (usageRes.code !== 0) {
    return `; usage unread — usage answered code ${usageRes.code}`
  }
  let parsed
  try {
    parsed = JSON.parse(usageRes.stdout)
  } catch {
    parsed = null
  }
  const first = Array.isArray(parsed) ? parsed[0] : undefined
  if (first === undefined || first.unread) {
    const reason = first?.reason ?? 'no readable JSON'
    return `; usage unread — ${reason}`
  }
  const { sevenDay, fiveHour } = first
  return `; 7d ${sevenDay.utilization}% resets ${sevenDay.resetsAt}` +
    `; 5h ${fiveHour.utilization}% resets ${fiveHour.resetsAt}`
}

/**
 * The bearer has to exist at the edge. Whether the object reaches a fleet VM
 * is the `integrations` row's question (its policy), not this one's.
 *
 * claude-token's status line only decorates the row. Either outcome leaves the
 * status alone — the bearer is injected at the edge whether or not this laptop
 * still holds the refresh token — and only the detail differs. The usage
 * window reading rides beside it, appended to `detail` either way, so the
 * reading is visible whether or not the bearer is found.
 */
function claudeRow (found, tokenRes, usageRes) {
  const suffix = usageSuffix(usageRes)
  if (found === null) {
    return row('claude', 'missing', `integrations list printed no readable JSON${suffix}`)
  }
  const have = found.get(OAUTH_INTEGRATION)
  if (have === undefined || !have.bearer) {
    const why = have === undefined
      ? `no ${OAUTH_INTEGRATION} integration at the edge`
      : `${OAUTH_INTEGRATION} carries no ${BEARER} header`
    return row('claude', 'missing', `${why} — node fleet/claude-token.mjs login${suffix}`)
  }
  const status = tokenRes.code === 0 && firstLine(tokenRes.stdout) !== ''
    ? firstLine(tokenRes.stdout)
    : 'no refresh token in the keychain — the bearer will not be refreshed before a run'
  return row('claude', 'ok', `${OAUTH_INTEGRATION} carries the bearer at the edge; ${status}${suffix}`)
}

// ── accounts ─────────────────────────────────────────────────────────────────

/** The command a laptop with no usable keychain entry runs. */
const LOGIN = 'node fleet/claude-token.mjs login'

/** The token the credential tool writes into `claude-max`'s comment on every
 *  install, so the edge itself records which account its bearer came from. */
const ACCOUNT_TOKEN = 'account='

/**
 * `claude-token.mjs accounts --json` prints one object per keychain entry —
 * `{ name, expiresAt, fresh }` — under the one service. Nothing secret is in
 * it: an expiry and a name, never a token.
 */
function parseAccounts (res) {
  if (res.code !== 0) return null
  const parsed = readJson(res.stdout)
  return Array.isArray(parsed) ? parsed : null
}

const accountName = (entry) => (entry && typeof entry.name === 'string' ? entry.name : '')

const describeAccount = (entry) =>
  `${accountName(entry)} ${entry?.fresh === true ? 'fresh until' : 'expired'} ${String(entry?.expiresAt ?? '')}`

/**
 * The account the edge carries, off `claude-max`'s comment: the value after
 * `account=` in the first whitespace-separated token that starts with it. Null
 * when the comment is prose with no such token — an install from before the
 * tool wrote one, which the next refresh records.
 */
function edgeAccount (found) {
  const comment = found?.get(OAUTH_INTEGRATION)?.comment
  if (typeof comment !== 'string') return null
  for (const word of comment.split(/\s+/)) {
    if (!word.startsWith(ACCOUNT_TOKEN)) continue
    const name = word.slice(ACCOUNT_TOKEN.length)
    return name === '' ? null : name
  }
  return null
}

/**
 * Which accounts this laptop holds, when each one expires, which of them the
 * edge is carrying, and — when `~/.ultrapowers/fleet.json` names one — whether
 * the keychain holds that name at all. An expired entry is not red: the
 * launcher refreshes before every run, and the bearer already lives at the
 * edge. An empty keychain is, because nothing can be refreshed from it.
 */
function accountsRow (res, found, account) {
  const entries = parseAccounts(res)
  if (entries === null) {
    return row(
      'accounts',
      'missing',
      `claude-token.mjs accounts --json answered code ${res.code} with no JSON array of keychain entries — ${LOGIN}`
    )
  }
  if (entries.length === 0) {
    return row('accounts', 'missing', `the keychain holds no account — ${LOGIN}`)
  }

  const listed = entries.map(describeAccount).join(', ')
  const edge = edgeAccount(found)
  const carries = edge === null ? '; edge account unrecorded' : `; edge carries ${edge}`
  if (account !== null && !entries.map(accountName).includes(account)) {
    return row(
      'accounts',
      'missing',
      `~/.ultrapowers/fleet.json names ${account}, which no keychain entry carries — ` +
        `${listed}${carries} — ${LOGIN} --account ${account}`
    )
  }
  const named = account === null ? '' : `; fleet.json names ${account}`
  return row('accounts', 'ok', `${listed}${carries}${named}`)
}

// ── verb-drift ───────────────────────────────────────────────────────────────

/** The only shape a verb name may take before it is interpolated into an ssh
 *  string. Any other key of the record is reported unreadable, never run. */
const VERB = /^[a-z][a-z0-9 -]*$/

/** The lobby's `Options:` block: two spaces, the flag, spaces, its description.
 *  `help <verb>` and `<verb> --help` print the same block (measured 2026-09-05),
 *  and `help …` is not a mutating verb, so this is the form the doctor asks. */
const FLAG_LINE = /^[ \t]+(--[A-Za-z0-9-]+)/gm

function helpFlags (stdout) {
  const flags = []
  for (const match of String(stdout ?? '').matchAll(FLAG_LINE)) {
    if (!flags.includes(match[1])) flags.push(match[1])
  }
  return flags
}

/**
 * Re-fetch `help <verb>` for every verb of the verb record (`VERBS_PATH`, or
 * `recordPath` so an exam drives the row from a fixture) and diff the live
 * flag set against the recorded one.
 *
 * `--help` answers text, not JSON — a `Command:` line, a description, an
 * optional `Usage:` line, an `Options:` block and an optional `Examples:` block
 * — so the diff unit is the flag set and the record stores flag names, not
 * prose. A verb the lobby no longer knows answers a line starting `No help
 * available for unrecognized command:` at exit 0, which is why a stdout with no
 * flag at all counts as unreadable whatever the exit code was.
 *
 * A drift is a finding, never a refusal: the caller decides what a finding is
 * worth. Only a record this cannot read at all answers `readable: false`.
 */
export async function verbDrift ({ help, recordPath } = {}) {
  const target = recordPath ?? VERBS_PATH
  const unreadable = (why) => ({
    readable: false,
    capturedAt: null,
    findings: [],
    detail: `${VERBS_RECORD} ${why} — re-capture it from ssh exe.dev "help <verb>" output`
  })

  let text
  try {
    text = await fsp.readFile(target, 'utf8')
  } catch {
    return unreadable('is not there')
  }
  let record
  try {
    record = JSON.parse(text)
  } catch {
    return unreadable('is not JSON')
  }
  const verbs = record && typeof record === 'object' ? record.verbs : null
  if (!verbs || typeof verbs !== 'object' || Array.isArray(verbs)) {
    return unreadable('carries no verbs object')
  }
  const capturedAt = typeof record.capturedAt === 'string' ? record.capturedAt : null

  const names = Object.keys(verbs)
  const findings = []
  const segments = []
  for (const verb of names) {
    const recorded = Array.isArray(verbs[verb]) ? verbs[verb].filter((f) => typeof f === 'string') : []

    if (!VERB.test(verb)) {
      findings.push({ verb, appeared: [], vanished: [], unreadable: -1 })
      segments.push(`${verb}: help unreadable (code -1)`)
      continue
    }

    const res = await help(verb)
    const live = helpFlags(res?.stdout)
    if (res?.code !== 0 || live.length === 0) {
      const code = typeof res?.code === 'number' ? res.code : -1
      findings.push({ verb, appeared: [], vanished: [], unreadable: code })
      segments.push(`${verb}: help unreadable (code ${code})`)
      continue
    }

    const appeared = live.filter((flag) => !recorded.includes(flag))
    const vanished = recorded.filter((flag) => !live.includes(flag))
    if (appeared.length === 0 && vanished.length === 0) continue
    findings.push({ verb, appeared, vanished, unreadable: null })
    if (appeared.length > 0) segments.push(`${verb}: ${appeared.join(', ')} appeared`)
    if (vanished.length > 0) segments.push(`${verb}: ${vanished.join(', ')} vanished`)
  }

  const detail = segments.length === 0
    ? `${names.length} verbs match ${VERBS_RECORD} (captured ${capturedAt})`
    : `drift since ${capturedAt}: ${segments.join('; ')} — re-measure the behaviours with node fleet/tests/probe_exe_facts.mjs`
  return { readable: true, capturedAt, findings, detail }
}

/** A readable record is a green row whatever it found; an unreadable one is the
 *  only red, because then the doctor has nothing to compare the lobby against. */
const verbDriftRow = (drift) => row('verb-drift', drift.readable ? 'ok' : 'missing', drift.detail)

// ── github ───────────────────────────────────────────────────────────────────

/**
 * `integrations setup github --list` has no `--json` (`--json` is a
 * flag-parsing error), so the row reads the two-line form it does print: a
 * `GitHub accounts:` header, then one indented account per line. No account
 * means the browser step has never been walked.
 */
function githubAccounts (stdout) {
  const lines = String(stdout ?? '').split('\n')
  const header = lines.findIndex((line) => /accounts\s*:\s*$/i.test(line))
  const body = header === -1 ? lines : lines.slice(header + 1)
  const names = []
  for (const line of body) {
    if (!/^\s+\S/.test(line)) continue
    names.push(line.trim())
  }
  return names
}

function githubRow (res) {
  const accounts = res.code === 0 ? githubAccounts(res.stdout) : []
  if (accounts.length === 0) {
    return row(
      'github',
      'missing',
      `integrations setup github --list answered code ${res.code} with no account — ssh exe.dev integrations setup github walks the browser step`
    )
  }
  return row('github', 'ok', `GitHub accounts ${accounts.join(', ')}`)
}

// ── integrations ─────────────────────────────────────────────────────────────

/**
 * The names the row asks about: the bearer's object always, and the target's
 * with `--target`. Each is read once with `integrations policy get <name>
 * --json`, in this order.
 */
function policyNames (target) {
  const names = [OAUTH_INTEGRATION]
  if (target !== null) names.push(targetIntegration(target))
  return names
}

/**
 * A credential reaches a fleet VM by the attachment policy on its integration
 * and by nothing else: exe.dev refuses `new --integration` and `integrations
 * attach` since 2026-09-11, so every integration a run needs has to carry the
 * policy `tag:fleet` — the tag `new --tag fleet` creates the VM with. The row
 * is red for the FIRST name whose `policy.selector` is anything else, naming
 * the get/set two-step that fixes it, because a stranger reading several
 * failures at once cannot tell which one to run first.
 *
 * With `--target`, the target's one object `gh-<owner>-<repo>` also has to
 * exist, and that is asked before its policy is. The listing's `attachments`
 * (which spells a policy-attached object as `tag:fleet` too) is not consulted:
 * the policy read is the edge's own answer, revision included.
 */
function integrationsRow (found, target, policies) {
  if (found === null) {
    return row('integrations', 'missing', 'integrations list printed no readable JSON')
  }
  if (target !== null) {
    const want = targetIntegration(target)
    if (!found.has(want)) {
      return row('integrations', 'missing', `no ${want} integration for ${target} — node fleet/target.mjs ${target}`)
    }
  }
  const names = policyNames(target)
  for (const name of names) {
    if (!found.has(name)) continue // the claude row names a missing object
    const off = policyRowFor(name, { id: 'integrations', found, policyRes: policies.get(name) })
    if (off !== null) return off
  }
  return row('integrations', 'ok', `${names.filter((n) => found.has(n)).join(', ')} on the policy ${FLEET_POLICY}`)
}

// ── kata ─────────────────────────────────────────────────────────────────────

/** The hub's VM, the integration that fronts it, and the one command that
 *  builds either. */
const KATA_INTEGRATION = 'kata'
const KATA_VM = 'kata-hub'
const KATA_FIX = 'node fleet/kata-hub.mjs'

/** `ssh exe.dev "ls kata-hub --json"` → the `kata-hub` row of `.vms[]`, or null.
 *  `.vms[]` only: `.shared_vms[]` are other people's machines. */
function kataVmRow (res) {
  if (!res || res.code !== 0) return null
  const parsed = readJson(res.stdout)
  const rows = Array.isArray(parsed?.vms) ? parsed.vms : []
  return rows.find((entry) => entry?.vm_name === KATA_VM) ?? null
}

/**
 * The hub, in three questions asked in the order an operator fixes them: the
 * object, its bearer, its policy, and then the VM behind it.
 *
 * The policy question is asked of `integrations policy get kata --json` and
 * never of the listing's `attachments`: an attachment array names the VMs a
 * live selector currently resolves to, so a hub whose policy is right reads as
 * a list of today's fleet VMs, and a hub attached to one VM by hand reads as a
 * plausible one. Only the selector says which.
 */
function kataRow (found, policyRes, vmsRes) {
  const have = found === null ? undefined : found.get(KATA_INTEGRATION)
  if (have === undefined) {
    return row('kata', 'missing', `no ${KATA_INTEGRATION} http-proxy at the edge — ${KATA_FIX}`)
  }
  if (!have.bearer) {
    return row('kata', 'missing', `${KATA_INTEGRATION} carries no ${BEARER} header — ${KATA_FIX}`)
  }
  const off = policyRowFor(KATA_INTEGRATION, { id: 'kata', found, policyRes })
  if (off !== null) return off
  const vm = kataVmRow(vmsRes)
  if (vm === null) {
    return row('kata', 'missing', `no ${KATA_VM} VM — ${KATA_FIX}`)
  }
  const status = typeof vm.status === 'string' && vm.status !== '' ? vm.status : 'unknown'
  return row(
    'kata',
    'ok',
    `${KATA_INTEGRATION} carries the bearer on the policy ${FLEET_POLICY}, and ${KATA_VM} is ${status}`
  )
}

// ── cloudflare ───────────────────────────────────────────────────────────────

/** The deploy's credential: an http-proxy integration that forwards a
 *  Cloudflare API token, named the same as every other fleet integration. */
const CLOUDFLARE_INTEGRATION = 'cloudflare'

/**
 * The ninth row: cloudflare carries the deploy's credential at the edge, and
 * only a plan with a `**Publish:**` line needs it — so unlike every other row,
 * absent is `ok`. Present is judged exactly as `kata`'s policy question is:
 * the listing's own attachment tag first, then the policy read (asked only
 * when the object exists at all — `doctor()` skips the read otherwise), red
 * for the first selector that is not `tag:fleet`.
 */
function cloudflareRow (found, policyRes) {
  const off = policyRowFor(CLOUDFLARE_INTEGRATION, {
    id: 'cloudflare',
    found,
    policyRes,
    absentIsOk: true,
    absentDetail: 'cloudflare integration absent — only a plan with a **Publish:** line needs it; ' +
      'first-run.md §cloudflare walks the token'
  })
  return off ?? row('cloudflare', 'ok', `${CLOUDFLARE_INTEGRATION} http-proxy on the policy ${FLEET_POLICY}`)
}

// ── the doctor ───────────────────────────────────────────────────────────────

/**
 * Run every row against `config` and resolve `{ config, rows, verdict }`.
 * `exec(cmd)` resolves `{ code, stdout }`, so a test drives the doctor with a
 * stub. `target` is `owner/repo` or null; anything else is refused before any
 * read rather than interpolated into an ssh string.
 *
 * `configKeys` is the config file's own top-level key names — `fleetConfigKeys`
 * for the same path `config` was loaded from, or null when there is no file.
 * It reaches the `capacity` row and nothing else: `result.config` stays exactly
 * the two keys the doctor reads.
 *
 * `account` is that file's own `account` — `fleetConfigAccount` for the same
 * path — and reaches the `accounts` row alone, for the same reason. `verbsPath`
 * overrides the verb record the `verb-drift` row reads.
 */
export async function doctor ({
  config, exec, target = null, configKeys = null, account = null, verbsPath = null
} = {}) {
  const cfg = { ...FLEET_DEFAULTS, ...(config ?? {}) }
  const run = exec ?? defaultExec
  const want = target === null || target === undefined ? null : String(target)
  if (want !== null && !isSafeTarget(want)) {
    throw new Error(`--target takes owner/repo, not ${JSON.stringify(want)}`)
  }
  const wantAccount = account === null || account === undefined ? null : String(account)

  const whoami = await run(READS.whoami)
  const billing = await run(READS.billing)
  const list = await run(READS.list)
  const found = list.code === 0 ? parseIntegrations(list.stdout) : null
  const github = await run(READS.github)
  // The status read names the configured account (`fleet.json` `account`), never
  // the code's default: the keychain entries are named by email since 2026-09-11.
  const token = await run(wantAccount ? `${READS.token} --account ${wantAccount}` : READS.token)
  // The usage read carries `--account` before `--no-rotate`, unlike the token
  // read's trailing clause, and never rotates the token it reads.
  const usage = await run(wantAccount
    ? `node ${CLAUDE_TOKEN} usage --json --account ${wantAccount} --no-rotate`
    : READS.usage)
  const accounts = await run(READS.accounts)
  // The hub's two reads: the policy that grants it, then the VM behind it.
  const kataPolicy = await run(READS.kataPolicy)
  const kataVms = await run(READS.kataVm)
  const policies = new Map()
  for (const name of policyNames(want)) {
    policies.set(name, await run(policyRead(name)))
  }
  // The ninth read: only when `found` names a cloudflare object at all — an
  // absent one needs no policy read, and most fleets never publish.
  const cloudflarePolicy = found !== null && found.has(CLOUDFLARE_INTEGRATION)
    ? await run(policyRead(CLOUDFLARE_INTEGRATION))
    : null
  const drift = await verbDrift({
    help: (verb) => run(`ssh exe.dev "help ${verb}"`),
    recordPath: verbsPath
  })

  const rows = [
    exeDevRow(whoami),
    capacityRow(billing, cfg, configKeys),
    claudeRow(found, token, usage),
    accountsRow(accounts, found, wantAccount),
    githubRow(github),
    integrationsRow(found, want, policies),
    verbDriftRow(drift),
    kataRow(found, kataPolicy, kataVms),
    cloudflareRow(found, cloudflarePolicy)
  ]
  const verdict = rows.every((r) => r.status === 'ok') ? 'ready' : 'not-ready'
  return { config: cfg, rows, verdict }
}

// ── CLI ──────────────────────────────────────────────────────────────────────

export function parseArgs (argv) {
  const opts = { json: false, configPath: null, target: null }
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i]
    if (arg === '--json') opts.json = true
    else if (arg === '--config') {
      i += 1
      opts.configPath = argv[i] ?? null
    } else if (arg === '--target') {
      i += 1
      opts.target = argv[i] ?? null
    }
  }
  return opts
}

const PAD = Math.max(...['ok', 'missing'].map((s) => s.length))

function renderRows (rows) {
  const out = []
  for (const r of rows) {
    out.push(`${r.status.padEnd(PAD)} ${r.id}  ${r.detail}`)
    if (r.status === 'missing') out.push(`    → references/first-run.md §${r.fix}`)
  }
  return out.join('\n')
}

async function main (argv) {
  const opts = parseArgs(argv)
  const configPath = opts.configPath ?? DEFAULT_CONFIG_PATH()
  const config = await loadFleetConfig({ path: configPath })
  const configKeys = await fleetConfigKeys({ path: configPath })
  const account = await fleetConfigAccount({ path: configPath })
  let result
  try {
    result = await doctor({ config, exec: defaultExec, target: opts.target, configKeys, account })
  } catch (error) {
    process.stderr.write(`${error.message}\n`)
    process.exitCode = 2
    return
  }
  process.stdout.write(
    opts.json ? `${JSON.stringify(result)}\n` : `${renderRows(result.rows)}\n`
  )
  process.exitCode = result.verdict === 'ready' ? 0 : 1
}

const invokedPath = process.argv[1] ? path.resolve(process.argv[1]) : ''
if (invokedPath === fileURLToPath(import.meta.url)) {
  await main(process.argv.slice(2))
}

